/* @autogenerated */
package net.civeira.phylax.integrationtest.features.oauth.flow;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.Tag;
import org.junit.jupiter.api.Test;

import io.quarkus.test.junit.QuarkusTest;
import io.restassured.response.Response;
import net.civeira.phylax.features.oauth.authentication.domain.AuthenticationResult;
import net.civeira.phylax.integrationtest.features.oauth.fixtures.OidcTestFixtures;

@Tag("oidc-flow")
@QuarkusTest
class SessionManagementTest extends OidcIntegrationTestBase {

  @Test
  void revocation_returns200() {
    // Trigger an MFA flow to get a PRE_SESSION_ID cookie
    loginGateway.whenValidate(
        () -> AuthenticationResult.mfaRequired(OidcTestFixtures.TENANT, OidcTestFixtures.USERNAME));

    Response login = client.submitLogin(OidcTestFixtures.TENANT, OidcTestFixtures.USERNAME,
        OidcTestFixtures.PASSWORD, null);
    String preSession = client.extractPreSessionCookie(login);
    Assertions.assertNotNull(preSession);

    // Revoke the pre-session
    Response revoke = client.revoke(OidcTestFixtures.TENANT, preSession);
    Assertions.assertEquals(200, revoke.statusCode());
  }

  @Test
  void logout_clears_session_and_redirects() {
    // Complete a login to get AUTH_SESSION_ID
    Response login = client.submitLogin(OidcTestFixtures.TENANT, OidcTestFixtures.USERNAME,
        OidcTestFixtures.PASSWORD, null);
    String authCookie = client.extractAuthSessionCookie(login);
    Assertions.assertNotNull(authCookie);

    // Logout with a post-logout redirect URI
    String postLogoutUri = "http://localhost/after-logout";
    Response logout = client.logout(OidcTestFixtures.TENANT, authCookie, postLogoutUri);

    // Verify redirect to post-logout URI (query params stripped)
    Assertions.assertEquals(302, logout.statusCode());
    String location = logout.getHeader("Location");
    Assertions.assertNotNull(location);
    Assertions.assertTrue(location.contains("after-logout"));
    Assertions.assertFalse(location.contains("?"),
        "Query params must be stripped from post-logout redirect URI");

    // AUTH_SESSION_ID cookie must be cleared
    String authSessionAfterLogout = logout.getCookie("AUTH_SESSION_ID");
    Assertions.assertTrue(authSessionAfterLogout == null || authSessionAfterLogout.isEmpty(),
        "AUTH_SESSION_ID must be empty after logout");

    // Subsequent auth flow with the old session shows login form (session deleted)
    Response reuse =
        client.startAuthFlowWithSession(OidcTestFixtures.TENANT, OidcTestFixtures.CLIENT_ID,
            OidcTestFixtures.REDIRECT_URI, OidcTestFixtures.SCOPE, authCookie);
    Assertions.assertEquals(200, reuse.statusCode());
    Assertions.assertTrue(reuse.getBody().asString().contains("name=\"username\""),
        "Login form must be shown when session has been deleted by logout");
  }
}
